INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020023, 111031, "ふむ…これは僥倖\nかくなる上は再び\n潜航してみるか…", 302, "", "", "", 10, 11, "", "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020024, 0, "", 302, "", "", "", "", 91, "", "");
