INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020026, 111031, "存外意義あるものだ\n資材ダイビングとか\nいう新種の探索行は", 302, "", "", "", 10, 11, "", "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020027, 0, 1, 302, "", "", "", "", 91, "", "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020028, 111031, "まあ万一溺れたとて\n後輩たちの誰ぞが\nきっと気付くだろう", 302, "", "", "", 10, 11, "", "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020029, 0, 1, 302, "", "", "", "", 91, "", "");
